/* Lifecycle is derived from the same records as the Lead table and detail. */
let leadViewMode='pipeline',leadPipelineStage='',leadPipelineLimits={};
const LEAD_PIPELINE_STAGES=['Baru','Dalam Kualifikasi','Qualified','Tidak Qualified','Dikonversi ke Opportunity','Dikonversi ke Customer','Ditutup'];
function leadPipelineGroups(rows){return LEAD_PIPELINE_STAGES.map(name=>({name,rows:rows.filter(l=>leadLifecycle(l)===name)}))}
function leadPipelineSelect(stage){leadPipelineStage=stage;leadChip='Semua';listPage=1;renderContent();persistWorkspaceLocation()}
const leadViewPositions=new Map();
function leadPipelineMode(mode){
 if(!['pipeline','list'].includes(mode)||mode===leadViewMode)return;
 const scope=typeof workspaceLocationKey==='function'?workspaceLocationKey():'leads';
 const positions=leadViewPositions.get(scope)||{};
 const board=document.querySelector('.lead-pipeline-board');
 positions[leadViewMode]={page:listPage,left:board?.scrollLeft||0,columns:board?[...board.querySelectorAll('.lead-pipeline-cards')].map(el=>el.scrollTop):[]};
 leadViewPositions.set(scope,positions);leadViewMode=mode;listPage=positions[mode]?.page||1;
 renderContent();persistWorkspaceLocation();
 const restore=()=>{
  const target=document.querySelector('.lead-pipeline-board'),saved=positions[mode];
  if(target&&saved){target.scrollLeft=saved.left;target.querySelectorAll('.lead-pipeline-cards').forEach((el,i)=>{el.scrollTop=saved.columns[i]||0})}
  document.querySelector('.crm-view-switch button[aria-pressed="true"]')?.focus({preventScroll:true});
 };
 if(typeof requestAnimationFrame==='function')requestAnimationFrame(restore);else restore();
}
function leadPipelineCard(l){const stage=leadLifecycle(l),locked=['Dikonversi ke Opportunity','Dikonversi ke Customer'].includes(stage);return '<article class="lead-pipeline-card"><button class="lead-pipeline-open" aria-label="'+E('Buka detail Lead '+pname(l.profile))+'" onclick="'+leadCall('go','Lead detail',l.id)+'"><span class="lead-card-top"><small class="lead-card-id">'+E(l.id)+'</small><span class="lead-card-grade">'+E(l.grade||'Belum dinilai')+'</span></span><strong class="lead-card-name">'+E(pname(l.profile))+'</strong><span class="lead-card-field"><small>Kebutuhan</small><span>'+E(l.need||'Kebutuhan belum dicatat')+'</span></span><span class="lead-card-field lead-card-product"><small>Produk diminati</small><span class="lead-pipeline-product">'+E(l.product||'Produk belum dipilih')+'</span></span><span class="lead-card-owner"><span class="lead-card-owner-icon" aria-hidden="true">'+E((l.owner||'?').trim().charAt(0))+'</span><span><small>Penanggung jawab</small><span>'+E(l.owner||'Belum ditetapkan')+'</span></span></span><span class="lead-card-sla">'+leadSlaBadge(l)+'</span></button><div class="lead-pipeline-actions">'+(locked?btn('Lihat keterkaitan',leadCall('go','Lead detail',l.id)):btn('Ubah tahap',leadCall('leadPipelineActions',l.id)))+btn('Buat Task',leadCall('newTask',l.profile,'',l.id))+'</div></article>'}

function leadPipelineBoard(rows){const groups=leadPipelineGroups(rows),active=LEAD_PIPELINE_STAGES.includes(leadChip)?leadChip:leadPipelineStage||groups.find(g=>g.rows.length)?.name||'Baru';return '<div class="lead-pipeline-guide"><p>Pipeline menunjukkan posisi Lead; nominal dan tahapan penjualan dikelola di Opportunity. Klik kartu untuk detail atau Ubah tahap untuk melanjutkan proses.</p><label class="lead-pipeline-mobile-stage">Tahap Lead<select aria-label="Tahap pipeline Leads" onchange="leadPipelineSelect(this.value)">'+groups.map(g=>'<option value="'+E(g.name)+'" '+(g.name===active?'selected':'')+'>'+E(g.name)+' ('+g.rows.length+')</option>').join('')+'</select></label><small>Geser horizontal untuk melihat tahap berikutnya. Chip dan filter di atas tetap berlaku.</small></div><div class="lead-pipeline-board" aria-label="Pipeline Leads">'+groups.map((g,i)=>'<section class="lead-pipeline-column '+(g.name===active?'selected':'')+'" data-stage="'+i+'" aria-label="'+E(g.name)+'"><header><h2>'+E(g.name)+'</h2><b>'+g.rows.length+'</b></header><div class="lead-pipeline-cards">'+g.rows.slice(0,leadPipelineLimits[g.name]||20).map(leadPipelineCard).join('')+(!g.rows.length?'<p class="lead-pipeline-empty">Tidak ada Lead sesuai filter.</p>':'')+(g.rows.length>(leadPipelineLimits[g.name]||20)?btn('Tampilkan 20 lagi',"leadPipelineLimits["+E(JSON.stringify(g.name))+"]="+((leadPipelineLimits[g.name]||20)+20)+";renderContent()"):'')+'</div></section>').join('')+'</div>'}
function leadPipelineActions(id){const l=db.leads.find(x=>x.id===id);if(!l||!mine(l))return toast('Lead tidak tersedia.');const stage=leadLifecycle(l);let actions='';if(stage==='Ditutup')actions=btn('Aktifkan kembali',leadCall('leadPipelineOpen','reopenRecord','lead',id));else if(!['Dikonversi ke Opportunity','Dikonversi ke Customer'].includes(stage)){if(stage==='Baru')actions+=btn('Mulai kualifikasi',leadCall('leadBeginQualification',id),true);actions+=btn('Isi hasil kualifikasi',leadCall('leadPipelineOpen','qualify',id));if(l.qualification==='Qualified'){actions+=btn('Buat Opportunity',leadCall('leadPipelineOpen','newOpp',l.profile,l.id),true);actions+=l.existingCustomer?btn('Buka Customer 360',leadCall('go','Nasabah detail',l.profile)):btn('Konversi ke Customer',leadCall('leadPipelineOpen','convertLeadCustomer',l.id));}actions+=btn('Tutup Lead',leadCall('leadPipelineOpen','closeLead',l.id));}modal('Lanjutkan Lead',detailFacts([['Nama',pname(l.profile)],['Tahap saat ini',stage],['Hasil kualifikasi',l.qualification||'Belum dinilai']])+'<div class="lead-pipeline-stage-actions">'+actions+'</div><p class="hint">Qualified memerlukan analisis kebutuhan dan potensi bisnis. Membuat Opportunity atau Customer mengikuti proses konversi agar semua keterkaitan tetap tersimpan.</p>',()=>{});document.querySelector('#form>.actions:last-child')?.remove()}
function leadPipelineOpen(name,...args){document.querySelector('#modal').close();const actions={qualify,newOpp,convertLeadCustomer,closeLead,reopenRecord};actions[name]?.(...args)}
async function leadBeginQualification(id){const l=db.leads.find(x=>x.id===id);if(!l||leadLifecycle(l)!=='Baru')return toast('Lead sudah berubah. Muat ulang data.');try{const r=await api('sync',{changes:[{collection:'leads',id:l.id,before:clone(l),next:{...l,status:'In qualification'}}],action:'Mulai kualifikasi Lead',object:l.id,detail:'Baru → Dalam Kualifikasi'});document.querySelector('#modal').close();applyServer(r);toast('Lead masuk Dalam Kualifikasi')}catch(e){toast(e.message)}}
const leadPipelineListBefore=scaleList;
scaleList=function(){const html=leadPipelineListBefore();if(view!=='Leads')return html;const root=document.createElement('div');root.innerHTML=html;const intro=root.querySelector('.intro');intro?.insertAdjacentHTML('afterend','<div class="lead-view-switch crm-view-switch" role="group" aria-label="Tampilan Leads"><button aria-pressed="'+(leadViewMode==='pipeline')+'" class="'+(leadViewMode==='pipeline'?'active':'')+'" onclick="leadPipelineMode(\'pipeline\')">Pipeline</button><button aria-pressed="'+(leadViewMode==='list')+'" class="'+(leadViewMode==='list'?'active':'')+'" onclick="leadPipelineMode(\'list\')">Daftar</button></div>');if(leadViewMode==='pipeline'){const head=root.querySelector('.listhead');if(head){while(head.nextSibling)head.nextSibling.remove();head.insertAdjacentHTML('afterend',leadPipelineBoard(getList('Leads')));}}return root.innerHTML};

if(typeof authUser!=='undefined'&&authUser&&!choosingBranch)render();
